def count_special_triplets(nums):
    from collections import Counter
    modulo=1000000007;left=Counter();right=Counter(nums);answer=0
    for middle in nums:
        right[middle]-=1;answer=(answer+left[2*middle]*right[2*middle])%modulo;left[middle]+=1
    return answer

